// Builds the Telegram message, shows yesterday's quiz answer, stores today's answer for tomorrow.
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let b;
try { b = JSON.parse($json.choices[0].message.content); }
catch (e) { throw new Error('OpenAI did not return valid JSON: ' + e.message); }
const store = $getWorkflowStaticData('global');   // persists only for the active (scheduled) workflow
let text = '';
if (store.lastQuiz) {
  text += `<b>Yesterday's answer:</b> ${esc(store.lastQuiz.answer)}\n<i>${esc(store.lastQuiz.explanation)}</i>\n\n`;
}
text += `<b>🌿 Perfume byte — ${esc(b.title)}</b>\n\n${esc(b.lesson)}\n\n`;
text += `<b>Say it to a supplier:</b> ${esc(b.say_supplier)}\n<b>Say it to a buyer:</b> ${esc(b.say_buyer)}\n\n`;
const opts = (b.quiz_options || []).map((o, i) => `${'ABC'[i]}) ${esc(o)}`).join('\n');
text += `<b>❓ Quiz:</b> ${esc(b.quiz_question)}\n${opts}\n<i>Answer tomorrow.</i>`;
store.lastQuiz = { answer: b.quiz_answer, explanation: b.quiz_explanation };
return [{ json: { text } }];
